import java.net.*; import java.io.*; public class TestHttp { public static void main(String[] args) throws Exception { HttpURLConnection conn = (HttpURLConnection) new URL("http://localhost:8081/MedRouteAI/auth/login").openConnection(); conn.setRequestMethod("POST"); conn.setDoOutput(true); OutputStream os = conn.getOutputStream(); os.write("email=admin@citygeneral.in&password=password123&csrfToken=ignore".getBytes()); os.flush(); String cookie = conn.getHeaderField("Set-Cookie"); if(cookie != null) cookie = cookie.split(";")[0]; HttpURLConnection api = (HttpURLConnection) new URL("http://localhost:8081/MedRouteAI/ai/analyze").openConnection(); api.setRequestMethod("POST"); api.setRequestProperty("Content-Type", "application/json"); api.setRequestProperty("Cookie", cookie); api.setDoOutput(true); api.getOutputStream().write("{\"medicineId\":999}".getBytes()); InputStream is; try { is = api.getInputStream(); } catch (Exception e) { is = api.getErrorStream(); } BufferedReader br = new BufferedReader(new InputStreamReader(is)); String line; while((line = br.readLine())!=null) System.out.println(line); } }